INTERNAL TYPES:
type msg =
  | Run of {
      messages : Pera_core.Agent_types.agent_message list;
      reply    : unit Eio.Promise.u;
    }

type 'ctx t = {
  config        : 'ctx Pera_core.Agent_loop.agent_loop_config;
  mailbox       : msg Eio.Stream.t;   (* capacity 1 *)
  mutable subscribers   : (Pera_core.Agent_types.agent_event -> unit) list;
  mutable is_running    : bool;
  mutable in_flight_tools : (string * string) list;  (* (tool_call_id, tool_name) pairs *)
  mutable messages      : Pera_core.Agent_types.agent_message list;
  sub_mutex     : Eio.Mutex.t;        (* protects subscribers list only *)
}

NOTE: in_flight_tools is keyed by tool_call_id (unique per call) so that two parallel calls to the same-named tool are tracked and removed independently. pending_tool_call_names maps the list to its tool_name components (snd).

CREATE (actor pattern):
let create ~config ~sw =
  let t = { config; mailbox = Eio.Stream.create 1; subscribers = [];
            is_running = false; in_flight_tools = []; messages = [];
            sub_mutex = Eio.Mutex.create () } in
  Eio.Fiber.fork ~sw (fun () ->
    let rec loop () =
      let (Run { messages; reply }) = Eio.Stream.take t.mailbox in
      t.is_running <- true;
      Fun.protect
        ~finally:(fun () ->
          t.is_running <- false;
          t.in_flight_tools <- [];
          Eio.Cancel.protect (fun () -> Eio.Promise.resolve reply ()))
        (fun () ->
          let stream = Pera_core.Agent_loop.run t.config ~messages ~sw in
          Pera_provider.Event_stream.iter stream ~f:(fun event ->
            update_state t event;
            let subs = Eio.Mutex.use_ro t.sub_mutex (fun () -> t.subscribers) in
            List.iter (fun sub -> sub event) subs)
          |> ignore);
      loop ()
    in
    loop ());
  t

SEND:
let send t ~messages =
  let p, resolver = Eio.Promise.create () in
  Eio.Stream.add t.mailbox (Run { messages; reply = resolver });
  Eio.Promise.await p

DESIGN NOTES:
- Eio.Stream.add blocks if mailbox full (capacity 1). A second send while one runs blocks the caller until actor takes the message and begins processing.
- Eio.Cancel.protect on Promise.resolve: ensures reply is always resolved even when sw is cancelled. Without this, send callers would block forever on cancelled runs.
- is_running not mutex-protected: Eio cooperative scheduling means external reads only happen at yield points, after is_running is set consistently.
- sub_mutex protects only subscribers list (subscribe/unsubscribe may come from any fibre).
- Fun.protect guarantees finally runs even on unexpected exceptions from Agent_loop.run.

SUBSCRIBE:
let subscribe t f =
  Eio.Mutex.use_rw ~protect:false t.sub_mutex (fun () ->
    t.subscribers <- t.subscribers @ [f]);
  (fun () ->
    Eio.Mutex.use_rw ~protect:false t.sub_mutex (fun () ->
      t.subscribers <- List.filter (fun sub -> not (sub == f)) t.subscribers))

UPDATE_STATE:
| AE_tool_execution_start {tool_call_id;tool_name;_} -> t.in_flight_tools <- (tool_call_id, tool_name) :: t.in_flight_tools
| AE_tool_execution_end {tool_call_id;_} -> t.in_flight_tools <- List.filter (fun (id, _) -> not (String.equal id tool_call_id)) t.in_flight_tools
| AE_agent_end {messages;_} -> t.messages <- messages
| _ -> ()

pending_tool_call_names t = List.map snd t.in_flight_tools

