SESSION_SUBSCRIBER (registered in create):
let session_subscriber writer event =
  let open Result.Syntax in
  let result = match event with
    | AE_message_end { message = Real (AssistantMessage am) } ->
        Session_writer.write_message writer (Provider.AssistantMessage am)
    | AE_message_end _ -> Ok ()
    | AE_turn_end { tool_results; _ } ->
        (* Write tool results only; the Leaf is written once per run at AE_agent_end. *)
        List.fold_left (fun acc tr ->
          let* () = acc in
          Session_writer.write_message writer (Provider.ToolResultMessage tr))
          (Ok ()) tool_results
    | AE_agent_end _ -> Session_writer.write_leaf writer
    | _ -> Ok ()
  in
  match result with
  | Ok () -> ()
  | Error e -> Printf.eprintf "session write error: %s\n%!" e.Pera_types.Types.message

SEND:
let send t text =
  if not t.session_info_written then (
    (match Session_writer.write_session_info t.writer with
    | Ok () -> () | Error e -> Printf.eprintf "session_info write: %s\n%!" e.message);
    t.session_info_written <- true);
  let um = Pera_provider.Provider.UserMessage
    Pera_types.Types.{ role = "user"; content = [ UText text ] } in
  (match Session_writer.write_message t.writer um with
  | Ok () -> () | Error e -> Printf.eprintf "user message write: %s\n%!" e.message);
  let agent_msg = Pera_core.Agent_types.Real um in
  let history = Pera_harness.Agent_wrapper.current_messages t.wrapper in
  let messages = history @ [ agent_msg ] in
  Pera_harness.Agent_wrapper.send t.wrapper ~messages

